namespace IfItQuacks.Generator;

internal static class EmbeddedSources
{
    public const string Attributes = """
        // <auto-generated/>
        #nullable enable
        namespace IfItQuacks
        {
            /// <summary>Marks a method whose interface parameters accept any type that structurally
            /// matches the interface, verified at compile time and dispatched via generated interceptors.</summary>
            [System.AttributeUsage(System.AttributeTargets.Method)]
            internal sealed class DuckTypedAttribute : System.Attribute
            {
            }

            /// <summary>Fills a partial interface with members derived from <typeparamref name="TSource"/>.
            /// Because matching is structural, every type carrying those members satisfies the result.</summary>
            [System.AttributeUsage(System.AttributeTargets.Interface, AllowMultiple = true)]
            internal sealed class DuckShapeAttribute<TSource> : System.Attribute
            {
                /// <summary>Only these members are derived. Mutually exclusive with <see cref="Omit"/>.</summary>
                public string[] Pick { get; set; } = new string[0];

                /// <summary>Every member except these is derived. Mutually exclusive with <see cref="Pick"/>.</summary>
                public string[] Omit { get; set; } = new string[0];

                /// <summary>Makes every derived member's type nullable.</summary>
                public bool Optional { get; set; }

                /// <summary>Drops the setters of the derived properties and indexers.</summary>
                public bool Readonly { get; set; }

                /// <summary>Derives methods, events and indexers as well, not only properties and fields.</summary>
                public bool IncludeMethods { get; set; }
            }

            /// <summary>Converts values to interfaces they structurally satisfy.</summary>
            internal static class Duck
            {
                /// <summary>Returns <paramref name="value"/> as <typeparamref name="TShape"/>. The call is verified at compile time and
                /// replaced by a generated adapter, or by a plain cast if the value already implements the interface.</summary>
                public static TShape As<TShape>(object value) where TShape : class
                {
                    return value as TShape ?? throw new DuckTypeMismatchException(value?.GetType() ?? typeof(object), typeof(TShape));
                }

                /// <summary>Copies <paramref name="value"/> into a new <typeparamref name="TTarget"/> built from the members of the
                /// same name. The call is verified at compile time; unlike <see cref="As{TShape}(object)"/> this does not forward.</summary>
                public static TTarget To<TTarget>(object value)
                {
                    return value is TTarget target
                        ? target
                        : throw new DuckTypeMismatchException(value?.GetType() ?? typeof(object), typeof(TTarget));
                }

                /// <summary>Returns <typeparamref name="TShape"/> built from several values, taking every member from the first
                /// value that provides it. The call is verified at compile time and replaced by a generated adapter.</summary>
                public static TShape Merge<TShape>(object first, object second) where TShape : class
                {
                    return first as TShape ?? second as TShape ??
                        throw new DuckTypeMismatchException(first?.GetType() ?? typeof(object), typeof(TShape));
                }

                /// <inheritdoc cref="Merge{TShape}(object, object)"/>
                public static TShape Merge<TShape>(object first, object second, object third) where TShape : class
                {
                    return first as TShape ?? second as TShape ?? third as TShape ??
                        throw new DuckTypeMismatchException(first?.GetType() ?? typeof(object), typeof(TShape));
                }

                /// <summary>Returns a test double for <typeparamref name="TShape"/>: members <paramref name="value"/> provides are
                /// forwarded to it, every other member throws <see cref="DuckStubException"/> when it is used.</summary>
                public static TShape Stub<TShape>(object value) where TShape : class
                {
                    return value as TShape ?? throw new DuckTypeMismatchException(value?.GetType() ?? typeof(object), typeof(TShape));
                }

                /// <summary>Returns a test double for <typeparamref name="TShape"/> whose members all throw <see cref="DuckStubException"/>.</summary>
                public static TShape Stub<TShape>() where TShape : class
                {
                    throw new DuckTypeMismatchException(typeof(object), typeof(TShape));
                }

                /// <summary>Returns the original instance behind a generated adapter, or <paramref name="value"/> itself
                /// if it is not an adapter (e.g. because its type already implements the interface).</summary>
                public static object? Unwrap(object? value) => value is IDuckAdapter adapter ? adapter.Value : value;
            }

            /// <summary>Implemented by every generated adapter to expose the instance it forwards to.</summary>
            [System.ComponentModel.EditorBrowsable(System.ComponentModel.EditorBrowsableState.Never)]
            internal interface IDuckAdapter
            {
                object? Value { get; }
            }

            /// <summary>Thrown when a member of a <see cref="Duck.Stub{TShape}()"/> that nothing implements is used.</summary>
            internal sealed class DuckStubException : System.NotImplementedException
            {
                public DuckStubException(string member)
                    : base($"Member '{member}' is not implemented by this duck stub.")
                {
                }
            }

            /// <summary>Thrown when a call that couldn't be verified at compile time (e.g. from generic code)
            /// receives a value that doesn't implement the interface at runtime. Verified mismatches are build errors instead.</summary>
            internal sealed class DuckTypeMismatchException : System.Exception
            {
                public DuckTypeMismatchException(System.Type actualType, System.Type shapeType)
                    : base($"Type '{actualType}' does not implement '{shapeType}' and could not be duck-typed at compile time.")
                {
                }
            }
        }
        """;

    public const string InterceptsLocationAttributePolyfill = """
        // <auto-generated/>
        #pragma warning disable CS9113 // positional parameters are read by the compiler itself, not by this type
        namespace System.Runtime.CompilerServices
        {
            [System.AttributeUsage(System.AttributeTargets.Method, AllowMultiple = true)]
            file sealed class InterceptsLocationAttribute(int version, string data) : System.Attribute
            {
            }
        }
        #pragma warning restore CS9113
        """;
}
